1	import { Fragment } from "react";
2	import { cn } from "@/lib/utils";
3	import { Badge } from "@/components/ui/badge";
4	import { Button } from "@/components/ui/button";
5	import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
6	import { XCircle } from "lucide-react";
7	import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
8	import { format } from "date-fns";
9	
10	interface StageTrackerProps {
11	  currentStage: HiringStage;
12	  updatedAt?: string | null;
13	  onStageChange: (stage: HiringStage) => void;
14	  disabled?: boolean;
15	}
16	
17	const STAGE_LABELS: Record<string, string> = {
18	  applied: "Applied",
19	  screened: "Screened",
20	  interview: "Interview",
21	  offer: "Offer",
22	  hired: "Hired",
23	};
24	
25	const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
26	  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
27	  const isRejected = currentStage === "rejected";
28	
29	  return (
30	    <div className="flex items-center gap-3 py-1">
31	      <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>
32	
33	      {/* Dots + connectors + labels */}
34	      <div className="flex-1 min-w-0">
35	        {/* Top row: dots and connectors */}
36	        <div className="flex items-center">
37	          {STAGE_ORDER.map((stage, i) => {
38	            const isCompleted = !isRejected && i < currentIndex;
39	            const isCurrent = !isRejected && i === currentIndex;
40	            const isUpcoming = isRejected || i > currentIndex;
41	
42	            return (
43	              <Fragment key={stage}>
44	                <TooltipProvider delayDuration={150}>
45	                  <Tooltip>
46	                    <TooltipTrigger asChild>
47	                      <button
48	                        disabled={disabled}
49	                        onClick={(e) => { e.stopPropagation(); onStageChange(stage); }}
50	                        className={cn(
51	                          "relative w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-bold transition-all duration-150 shrink-0",
52	                          "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-1",
53	                          isCompleted && "bg-emerald-500 text-white dark:bg-emerald-600 shadow-sm",
54	                          isCurrent && "bg-primary text-primary-foreground ring-2 ring-primary/30 shadow-sm",
55	                          isUpcoming && "bg-muted border border-border text-muted-foreground",
56	                          !disabled && "cursor-pointer hover:scale-110 hover:shadow",
57	                          disabled && "cursor-default"
58	                        )}
59	                      >
60	                        {isCompleted ? "✓" : i + 1}
61	                      </button>
62	                    </TooltipTrigger>
63	                    <TooltipContent className="text-xs">
64	                      {isCompleted
65	                        ? `${STAGE_LABELS[stage]} — done`
66	                        : isCurrent
67	                        ? `${STAGE_LABELS[stage]} — current stage`
68	                        : `Move to ${STAGE_LABELS[stage]}`}
69	                    </TooltipContent>
70	                  </Tooltip>
71	                </TooltipProvider>
72	
73	                {i < STAGE_ORDER.length - 1 && (
74	                  <div className={cn(
75	                    "h-px flex-1 min-w-[16px] max-w-[48px] transition-colors duration-200 shrink-0",
76	                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
77	                  )} />
78	                )}
79	              </Fragment>
80	            );
81	          })}
82	        </div>
83	
84	        {/* Bottom row: labels aligned under each dot */}
85	        <div className="flex items-start mt-1.5">
86	          {STAGE_ORDER.map((stage, i) => {
87	            const isCompleted = !isRejected && i < currentIndex;
88	            const isCurrent = !isRejected && i === currentIndex;
89	
90	            return (
91	              <Fragment key={stage}>
92	                <span className={cn(
93	                  "w-6 text-center text-[11px] leading-none",
94	                  isCompleted && "text-emerald-600 dark:text-emerald-400",
95	                  isCurrent && "text-primary font-semibold",
96	                  !isCompleted && !isCurrent && "text-muted-foreground"
97	                )}>
98	                  {STAGE_LABELS[stage]}
99	                </span>
100	                {i < STAGE_ORDER.length - 1 && (
101	                  <div className="flex-1 min-w-[16px] max-w-[48px]" />
102	                )}
103	              </Fragment>
104	            );
105	          })}
106	        </div>
107	      </div>
108	
109	      {/* Reject button — visible on all screen sizes */}
110	      <TooltipProvider delayDuration={150}>
111	        <Tooltip>
112	          <TooltipTrigger asChild>
113	            <Button
114	              variant="ghost"
115	              size="icon"
116	              disabled={disabled}
117	              className={cn(
118	                "h-7 w-7 shrink-0",
119	                isRejected
120	                  ? "text-destructive bg-destructive/10 hover:bg-destructive/20"
121	                  : "text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
122	              )}
123	              onClick={(e) => { e.stopPropagation(); onStageChange("rejected"); }}
124	            >
125	              <XCircle className="h-3.5 w-3.5" />
126	            </Button>
127	          </TooltipTrigger>
128	          <TooltipContent className="text-xs">
129	            {isRejected ? "Click any stage to restore" : "Reject candidate"}
130	          </TooltipContent>
131	        </Tooltip>
132	      </TooltipProvider>
133	
134	      {/* Rejected badge */}
135	      {isRejected && (
136	        <Badge variant="destructive" className="text-[11px] shrink-0">Rejected</Badge>
137	      )}
138	
139	      {/* Updated timestamp */}
140	      {updatedAt && (() => {
141	        try {
142	          return (
143	            <span className="text-[11px] text-muted-foreground shrink-0">
144	              Updated {format(new Date(updatedAt), "MMM d")}
145	            </span>
146	          );
147	        } catch {
148	          return null;
149	        }
150	      })()}
151	    </div>
152	  );
153	};
154	
155	export default StageTracker;
