208	          open={emailDialogOpen}
209	          onOpenChange={setEmailDialogOpen}
210	          candidateName={r.candidate_name || r.filename}
211	          candidateEmail={r.candidate_email}
212	          jobTitle={jobTitle || "Open Position"}
213	          matchScore={Math.round(r.overall_score ?? 0)}
214	          resumeId={r.resume_id}
215	          jobId={jobId || ""}
216	        />
217	      )}
218	    </>
219	  );
220	};
221	
222	export default React.memo(CandidateRow);
